problems.sol:
import sys
if len(sys.argv) < 2:
    print("Usage: python greet.py NAME")
else:
    print(f"Hello, {sys.argv[1]}!")

counts = {"INFO": 0, "WARNING": 0, "ERROR": 0}
errors = []
with open("app.log") as f:
    for line in f:
        parts = line.split()
        level = parts[2]
        if level in counts:
            counts[level] += 1
        if level == "ERROR":
            errors.append(line.strip())
print(counts)
for e in errors:
    print(e)

