problems.sol:
import math
import statistics as st
xs = [10, 12, 23, 23, 16, 23, 21, 16]

def mean(xs):
    return sum(xs) / len(xs)

def variance(xs):
    m = mean(xs)
    return sum((x - m) ** 2 for x in xs) / len(xs)

def std(xs):
    return math.sqrt(variance(xs))

print("Mean:", round(mean(xs), 2))
print("Variance:", round(variance(xs), 2))
print("Std:", round(std(xs), 2))
print("Matches statistics:", math.isclose(std(xs), st.pstdev(xs)))

import pandas as pd
df = pd.read_csv("messy.csv")
df["name"] = df["name"].str.strip().str.title()

def grade(m):
    if pd.isna(m):
        return "NA"
    if m >= 80:
        return "A"
    if m >= 70:
        return "B"
    return "C"

df["grade"] = df["marks"].apply(grade)
print(df[["name", "grade"]].to_string(index=False))

