class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def show(self):
        print(f"{self.name} has {self.marks} marks")

s1 = Student("Asha", 82)
s2 = Student("Ravi", 67)
s1.show()
s2.show()

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def is_square(self):
        return self.width == self.height

for w, h in [(4, 4), (3, 5)]:
    r = Rectangle(w, h)
    print(r.area(), r.perimeter(), r.is_square())

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient funds")
        else:
            self.balance -= amount

    def show_balance(self):
        print(f"{self.owner}: {self.balance}")

acc = BankAccount("Asha", 500)
acc.deposit(250)
acc.withdraw(1000)
acc.withdraw(300)
acc.show_balance()

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    def to_fahrenheit(self):
        return round(self.celsius * 9 / 5 + 32, 2)

    def to_kelvin(self):
        return round(self.celsius + 273.15, 2)

t = Temperature(36.6)
print(t.to_fahrenheit())
print(t.to_kelvin())

class Animal:
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "Woof"

class Cat(Animal):
    def speak(self):
        return "Meow"

for a in [Dog(), Cat(), Animal()]:
    print(type(a).__name__, a.speak())

class BankAccount:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

class SavingsAccount(BankAccount):
    def __init__(self, owner, balance, rate):
        super().__init__(owner, balance)
        self.rate = rate

    def add_interest(self):
        self.balance += self.balance * self.rate / 100

acc = SavingsAccount("Asha", 1000, 5)
acc.deposit(500)
acc.add_interest()
print(acc.balance)

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __str__(self):
        return f"({self.x}, {self.y})"

print(Vector(1, 2) + Vector(3, 4))

class Book:
