def log_call(func):
    def wrapper(*args, **kwargs):
        print("Calling", func.__name__, "with", args)
        result = func(*args, **kwargs)
        print("Result:", result)
        return result
    return wrapper

@log_call
def add(a, b):
    return a + b

add(2, 3)

class Circle:
    def __init__(self, radius):
        self.radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("radius cannot be negative")
        self._radius = value

    @property
    def area(self):
        return round(3.14159 * self._radius ** 2, 2)

c = Circle(3)
print(c.area)
try:
    c.radius = -1
except ValueError as e:
    print("Error:", e)

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    @classmethod
    def from_string(cls, text):
        name, salary = text.split("-")
        return cls(name, int(salary))

    @staticmethod
    def is_valid_salary(x):
        return x > 0

e = Employee.from_string("Asha-50000")
print(e.name, e.salary)
print(Employee.is_valid_salary(-5))

def repeat(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(n):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(3)
def hello():
    print("Hello")

hello()

class Money:
    def __init__(self, amount, currency):
        self.amount = amount
        self.currency = currency

    def __add__(self, other):
        if self.currency != other.currency:
            raise ValueError("currency mismatch")
        return Money(self.amount + other.amount, self.currency)

    def __eq__(self, other):
        return self.amount == other.amount and self.currency == other.currency

    def __lt__(self, other):
        return self.amount < other.amount

    def __repr__(self):
        return f"Money({self.amount}, '{self.currency}')"

print(Money(5, "INR") + Money(7, "INR"))
print(Money(5, "INR") == Money(5, "INR"))
print(Money(5, "INR") < Money(7, "INR"))

