import os, shutil

GROUPS = {".jpg": "Images", ".png": "Images", ".pdf": "Documents", ".docx": "Documents", ".txt": "Documents"}

def organize(folder):
    for name in os.listdir(folder):
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            continue
        ext = os.path.splitext(name)[1].lower()
        target = os.path.join(folder, GROUPS.get(ext, "Others"))
        os.makedirs(target, exist_ok=True)
        shutil.move(path, os.path.join(target, name))

os.makedirs("test_folder", exist_ok=True)
for n in ["a.jpg", "b.png", "c.pdf", "d.txt", "e.zip"]:
    open(os.path.join("test_folder", n), "w").close()
organize("test_folder")
for sub in sorted(os.listdir("test_folder")):
    print(sub, sorted(os.listdir(os.path.join("test_folder", sub))))

